BEGIN;
DO $$BEGIN IF to_regprocedure('zoi.suite_current_session()')IS NULL OR to_regprocedure('zoi.home_content_authorize(uuid,uuid)')IS NULL OR to_regprocedure('public.social_save_post(uuid,text,text[],timestamptz,text,jsonb,text,jsonb,uuid)')IS NULL THEN RAISE EXCEPTION 'editorial_dependency_unavailable';END IF;END$$;
CREATE TABLE zoi.editorial_sources(id text PRIMARY KEY,revision integer NOT NULL CHECK(revision>0),record jsonb NOT NULL CHECK(record->>'id'IS NOT DISTINCT FROM id AND record->>'revision'IS NOT DISTINCT FROM revision::text),active boolean NOT NULL DEFAULT true);
CREATE TABLE zoi.editorial_draft_links(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES zoi.workspaces(id),source_id text NOT NULL REFERENCES zoi.editorial_sources(id),source_revision integer NOT NULL,occurrence_date date NOT NULL,time_zone text NOT NULL,jurisdiction text NOT NULL,context jsonb NOT NULL,context_hash text NOT NULL,source_snapshot jsonb NOT NULL,post_id uuid UNIQUE REFERENCES zoi.social_posts(id)ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,source_id,occurrence_date,time_zone,jurisdiction,context_hash));
CREATE TABLE zoi.editorial_draft_receipts(request_id uuid PRIMARY KEY,actor_auth uuid NOT NULL,workspace_id uuid NOT NULL REFERENCES zoi.workspaces(id),payload jsonb NOT NULL,link_id uuid NOT NULL REFERENCES zoi.editorial_draft_links(id),post_snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE zoi.editorial_sources ENABLE ROW LEVEL SECURITY;ALTER TABLE zoi.editorial_draft_links ENABLE ROW LEVEL SECURITY;ALTER TABLE zoi.editorial_draft_receipts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON zoi.editorial_sources,zoi.editorial_draft_links,zoi.editorial_draft_receipts FROM PUBLIC,anon,authenticated;
CREATE INDEX editorial_draft_links_source ON zoi.editorial_draft_links(source_id);
CREATE FUNCTION zoi.editorial_source_revision_guard()RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$BEGIN IF(NEW.record IS DISTINCT FROM OLD.record OR NEW.active IS DISTINCT FROM OLD.active)AND NEW.revision<=OLD.revision THEN RAISE EXCEPTION 'editorial_source_revision_must_increase';END IF;RETURN NEW;END$$;
CREATE TRIGGER editorial_source_revision_guard BEFORE UPDATE ON zoi.editorial_sources FOR EACH ROW EXECUTE FUNCTION zoi.editorial_source_revision_guard();
REVOKE ALL ON FUNCTION zoi.editorial_source_revision_guard()FROM PUBLIC,anon,authenticated;
CREATE FUNCTION zoi.editorial_source_cancel_queued()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN IF NEW.revision IS DISTINCT FROM OLD.revision OR NEW.record IS DISTINCT FROM OLD.record OR NEW.active IS DISTINCT FROM OLD.active THEN UPDATE zoi.social_posts p SET status='draft',scheduled_at=NULL,updated_at=now()FROM zoi.editorial_draft_links l WHERE l.source_id=NEW.id AND l.post_id=p.id AND p.workspace_id=l.workspace_id AND p.status='scheduled'AND(l.source_revision<>NEW.revision OR l.source_snapshot<>NEW.record OR NOT NEW.active);END IF;RETURN NEW;END$$;
CREATE TRIGGER editorial_source_cancel_queued AFTER UPDATE ON zoi.editorial_sources FOR EACH ROW EXECUTE FUNCTION zoi.editorial_source_cancel_queued();
REVOKE ALL ON FUNCTION zoi.editorial_source_cancel_queued()FROM PUBLIC,anon,authenticated;
CREATE FUNCTION zoi.editorial_schedule_source_guard()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE l zoi.editorial_draft_links;r zoi.editorial_sources;BEGIN IF NEW.status NOT IN('scheduled','published')THEN RETURN NEW;END IF;SELECT *INTO l FROM zoi.editorial_draft_links WHERE post_id=NEW.id;IF NOT FOUND THEN RETURN NEW;END IF;IF NEW.status='scheduled'AND(OLD.status IS DISTINCT FROM NEW.status OR OLD.scheduled_at IS DISTINCT FROM NEW.scheduled_at)AND auth.uid()IS NOT NULL THEN PERFORM zoi.editorial_draft_actor(NEW.workspace_id);END IF;SELECT *INTO r FROM zoi.editorial_sources WHERE id=l.source_id;IF r.id IS NULL OR NOT r.active OR r.revision<>l.source_revision OR r.record<>l.source_snapshot THEN RAISE EXCEPTION 'editorial_source_changed';END IF;IF NEW.workspace_id<>l.workspace_id OR NEW.scheduled_at IS NULL OR(NEW.scheduled_at AT TIME ZONE l.time_zone)::date<>l.occurrence_date THEN RAISE EXCEPTION 'editorial_schedule_occurrence_mismatch';END IF;RETURN NEW;END$$;
CREATE TRIGGER editorial_schedule_source_guard BEFORE UPDATE ON zoi.social_posts FOR EACH ROW EXECUTE FUNCTION zoi.editorial_schedule_source_guard();
REVOKE ALL ON FUNCTION zoi.editorial_schedule_source_guard()FROM PUBLIC,anon,authenticated;
CREATE FUNCTION zoi.editorial_draft_actor(p_workspace uuid)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE actor uuid;BEGIN
 PERFORM zoi.suite_current_session();SELECT up.id INTO actor FROM zoi.user_profiles up JOIN zoi.workspace_members wm ON wm.profile_id=up.id WHERE up.auth_user_id=auth.uid()AND wm.workspace_id=p_workspace AND wm.role IN('owner','admin','editor')FOR SHARE OF up,wm;IF actor IS NULL THEN RAISE EXCEPTION 'editorial_not_authorized' USING ERRCODE='42501';END IF;PERFORM zoi.suite_current_session();RETURN actor;END$$;
CREATE FUNCTION public.editorial_sources_get(p_workspace uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$BEGIN PERFORM zoi.editorial_draft_actor(p_workspace);RETURN jsonb_build_object('ok',true,'sources',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'revision',revision,'record',record)ORDER BY id)FROM zoi.editorial_sources WHERE active),'[]'::jsonb));END$$;
CREATE FUNCTION public.editorial_draft_get(p_workspace uuid,p_link uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE l zoi.editorial_draft_links;p zoi.social_posts;BEGIN PERFORM zoi.editorial_draft_actor(p_workspace);SELECT *INTO l FROM zoi.editorial_draft_links WHERE id=p_link AND workspace_id=p_workspace;IF NOT FOUND THEN RAISE EXCEPTION 'editorial_draft_unavailable';END IF;IF l.context?'listing'THEN PERFORM zoi.home_content_authorize(p_workspace,(l.context->>'listing')::uuid);END IF;SELECT *INTO p FROM zoi.social_posts WHERE id=l.post_id AND workspace_id=p_workspace;PERFORM zoi.suite_current_session();RETURN jsonb_build_object('ok',true,'workspace',p_workspace,'link',to_jsonb(l),'source_current',EXISTS(SELECT 1 FROM zoi.editorial_sources s WHERE s.id=l.source_id AND s.active AND s.revision=l.source_revision AND s.record=l.source_snapshot),'post',CASE WHEN p.id IS NULL THEN NULL ELSE to_jsonb(p)END);END$$;
CREATE FUNCTION public.editorial_draft_prepare(p_workspace uuid,p_source text,p_revision integer,p_year integer,p_time_zone text,p_jurisdiction text,p_request uuid,p_context jsonb DEFAULT '{}'::jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid;r zoi.editorial_sources;l zoi.editorial_draft_links;prior zoi.editorial_draft_receipts;p zoi.social_posts;ctx jsonb;payload jsonb;d date;client uuid;copy text;links text;already boolean:=false;
BEGIN
 actor:=zoi.editorial_draft_actor(p_workspace);
 IF p_request IS NULL OR p_source IS NULL OR char_length(p_source)>120 OR p_revision IS NULL OR p_year IS NULL OR p_year NOT BETWEEN 1900 AND 2200 OR p_time_zone IS NULL OR NOT EXISTS(SELECT 1 FROM pg_catalog.pg_timezone_names WHERE name=p_time_zone)OR p_jurisdiction IS NULL OR char_length(p_jurisdiction)>160 OR jsonb_typeof(p_context)IS DISTINCT FROM'object'OR octet_length(p_context::text)>2000 OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_context)k WHERE k NOT IN('campaign','listing'))OR(p_context?'campaign'AND jsonb_typeof(p_context->'campaign')NOT IN('string','null'))OR char_length(coalesce(p_context->>'campaign',''))>200 OR(p_context?'listing'AND p_context->'listing'<>'null'::jsonb AND(jsonb_typeof(p_context->'listing')<>'string'OR p_context->>'listing'!~'^[0-9a-fA-F]{8}-(?:[0-9a-fA-F]{4}-){3}[0-9a-fA-F]{12}$'))THEN RAISE EXCEPTION 'invalid_editorial_context';END IF;
 client:=nullif(p_context->>'listing','')::uuid;IF client IS NOT NULL THEN PERFORM zoi.home_content_authorize(p_workspace,client);END IF;ctx:=jsonb_strip_nulls(jsonb_build_object('campaign',nullif(btrim(p_context->>'campaign'),''),'listing',client));payload:=jsonb_build_object('source',p_source,'revision',p_revision,'year',p_year,'time_zone',p_time_zone,'jurisdiction',p_jurisdiction,'context',ctx);
 PERFORM pg_advisory_xact_lock(hashtextextended('editorial-request:'||p_request::text,0));SELECT *INTO prior FROM zoi.editorial_draft_receipts WHERE request_id=p_request;
 IF FOUND THEN
  IF prior.actor_auth<>auth.uid()OR prior.workspace_id<>p_workspace OR prior.payload<>payload THEN RAISE EXCEPTION 'editorial_request_conflict';END IF;
  SELECT *INTO l FROM zoi.editorial_draft_links WHERE id=prior.link_id;SELECT *INTO p FROM zoi.social_posts WHERE id=l.post_id AND workspace_id=p_workspace;PERFORM zoi.suite_current_session();RETURN jsonb_build_object('ok',true,'workspace',p_workspace,'request_id',p_request,'link',to_jsonb(l),'post_snapshot',prior.post_snapshot,'post',CASE WHEN p.id IS NULL THEN NULL ELSE to_jsonb(p)END,'replayed',true,'status',CASE WHEN p.id IS NULL THEN 'removed'ELSE 'saved'END);
 END IF;
 SELECT *INTO r FROM zoi.editorial_sources WHERE id=p_source AND active FOR SHARE;IF NOT FOUND OR r.revision<>p_revision THEN RAISE EXCEPTION 'editorial_source_changed';END IF;
 IF r.record->>'review'IS DISTINCT FROM'reviewed'OR coalesce(r.record->'conflicts','[null]'::jsonb)<>'[]'::jsonb OR jsonb_typeof(r.record->'evidence')IS DISTINCT FROM'array'OR jsonb_array_length(r.record->'evidence')=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements(r.record->'evidence')e WHERE e->>'primary'IS DISTINCT FROM'true'OR coalesce(e->>'url','')!~'^https://[^ /]+/'OR e->>'checked_at'IS NULL OR(e->>'checked_at')::date>current_date OR(e->>'checked_at')::date<current_date-180)THEN RAISE EXCEPTION 'editorial_source_review_required';END IF;
 IF coalesce(r.record#>>'{date,precision}','')NOT IN('day','month_day')OR coalesce(r.record#>>'{date,calendar}','')NOT IN('gregorian','goarch_fixed_civil')OR p_year<=coalesce((r.record#>>'{date,year}')::integer,0)THEN RAISE EXCEPTION 'editorial_exact_date_required';END IF;
 IF r.record->>'jurisdiction'IS DISTINCT FROM p_jurisdiction OR(r.record->>'kind'='release'AND(r.record#>>'{release,edition}'IS DISTINCT FROM'original'OR r.record#>>'{release,original_date_confirmed}'IS DISTINCT FROM'true'))THEN RAISE EXCEPTION 'editorial_jurisdiction_or_release_review_required';END IF;
 BEGIN d:=make_date(p_year,(r.record#>>'{date,month}')::integer,(r.record#>>'{date,day}')::integer);EXCEPTION WHEN datetime_field_overflow THEN RAISE EXCEPTION 'editorial_occurrence_not_in_year';END;
 IF d IS NULL OR d<(clock_timestamp()AT TIME ZONE p_time_zone)::date THEN RAISE EXCEPTION 'editorial_past_occurrence';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('editorial-occurrence:'||p_workspace::text||p_source||d::text||p_time_zone||p_jurisdiction||ctx::text,0));SELECT *INTO l FROM zoi.editorial_draft_links WHERE workspace_id=p_workspace AND source_id=p_source AND occurrence_date=d AND time_zone=p_time_zone AND jurisdiction=p_jurisdiction AND context_hash=md5(ctx::text)FOR UPDATE;
 IF FOUND THEN IF l.source_revision<>r.revision OR l.source_snapshot<>r.record THEN RAISE EXCEPTION 'editorial_source_changed';END IF;IF l.context<>ctx THEN RAISE EXCEPTION 'editorial_context_conflict';END IF;SELECT *INTO p FROM zoi.social_posts WHERE id=l.post_id AND workspace_id=p_workspace FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'editorial_draft_previously_removed';END IF;already:=true;
 ELSE
  SELECT string_agg(e->>'url',E'\n')INTO links FROM jsonb_array_elements(r.record->'evidence')e;copy:=r.record->>'copy';IF copy IS NULL OR char_length(copy)>4000 THEN RAISE EXCEPTION 'editorial_source_copy_invalid';END IF;
  SELECT *INTO p FROM public.social_save_post(p_workspace,copy||E'\n\nSource: '||links,'{}'::text[],NULL,'draft','[]'::jsonb,NULL,jsonb_build_object('source','editorial-calendar','campaign',ctx->'campaign','client_listing_id',ctx->'listing','editorial',jsonb_build_object('source_id',r.id,'revision',r.revision,'occurrence_date',d,'time_zone',p_time_zone,'jurisdiction',p_jurisdiction,'source_snapshot',r.record,'review_before_publication',true)),NULL);
  IF p.id IS NULL OR p.workspace_id<>p_workspace OR p.status<>'draft'OR p.channels<>'{}'::text[]OR p.scheduled_at IS NOT NULL OR p.author_profile IS DISTINCT FROM actor OR p.body IS DISTINCT FROM copy||E'\n\nSource: '||links OR p.media IS DISTINCT FROM '[]'::jsonb OR p.meta#>>'{editorial,source_id}'IS DISTINCT FROM r.id OR p.meta#>>'{editorial,revision}'IS DISTINCT FROM r.revision::text THEN RAISE EXCEPTION 'editorial_canonical_save_unconfirmed';END IF;
  INSERT INTO zoi.editorial_draft_links(workspace_id,source_id,source_revision,occurrence_date,time_zone,jurisdiction,context,context_hash,source_snapshot,post_id)VALUES(p_workspace,r.id,r.revision,d,p_time_zone,p_jurisdiction,ctx,md5(ctx::text),r.record,p.id)RETURNING *INTO l;
 END IF;
 INSERT INTO zoi.editorial_draft_receipts(request_id,actor_auth,workspace_id,payload,link_id,post_snapshot)VALUES(p_request,auth.uid(),p_workspace,payload,l.id,to_jsonb(p));PERFORM zoi.suite_current_session();RETURN jsonb_build_object('ok',true,'workspace',p_workspace,'request_id',p_request,'link',to_jsonb(l),'post',to_jsonb(p),'post_snapshot',to_jsonb(p),'already_saved',already,'status','saved');
END$$;
REVOKE ALL ON FUNCTION zoi.editorial_draft_actor(uuid),public.editorial_sources_get(uuid),public.editorial_draft_get(uuid,uuid),public.editorial_draft_prepare(uuid,text,integer,integer,text,text,uuid,jsonb)FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.editorial_sources_get(uuid),public.editorial_draft_get(uuid,uuid),public.editorial_draft_prepare(uuid,text,integer,integer,text,text,uuid,jsonb)TO authenticated;
-- Only two source dates were rechecked in official indexed publisher pages on Oct14.
-- Direct requests returned403; evidence honestly records indexed_official_source.
INSERT INTO zoi.editorial_sources VALUES('seferis-nobel-lecture',1,'{"id":"seferis-nobel-lecture","revision":1,"kind":"anniversary","subject":"Giorgos Seferis’s Nobel Lecture","date":{"precision":"day","year":1963,"month":12,"day":11,"calendar":"gregorian"},"jurisdiction":"cultural","review":"reviewed","conflicts":[],"sensitive":false,"evidence":[{"url":"https://www.nobelprize.org/prizes/literature/1963/seferis/lecture/","publisher":"Nobel Prize","claim":"The official lecture is dated 11 December 1963.","checked_at":"2026-10-14","method":"indexed_official_source","primary":true}],"copy":"On 11 December 1963, Giorgos Seferis delivered his Nobel Lecture. Explore the lecture in the Nobel Prize archive."}',true),('goarch-dormition',1,'{"id":"goarch-dormition","revision":1,"kind":"ecclesiastical","subject":"Dormition of the Theotokos","date":{"precision":"month_day","month":8,"day":15,"calendar":"goarch_fixed_civil"},"jurisdiction":"Greek Orthodox Archdiocese of America","review":"reviewed","conflicts":[],"sensitive":true,"evidence":[{"url":"https://www.goarch.org/dormition","publisher":"Greek Orthodox Archdiocese of America","claim":"The Archdiocese gives 15 August each year for this feast.","checked_at":"2026-10-14","method":"indexed_official_source","primary":true}],"copy":"The Greek Orthodox Archdiocese of America observes the Dormition of the Theotokos on 15 August. A moment for prayer and reflection for those who observe the feast."}',true);
NOTIFY pgrst,'reload schema';
COMMIT;
